def solve(s: str):
    """Return list of [character, count] for each consecutive run in s."""
    if not s:
        return []
    res = []
    current_char = s[0]
    count = 1
    for ch in s[1:]:
        if ch == current_char:
            count += 1
        else:
            res.append([current_char, count])
            current_char = ch
            count = 1
    res.append([current_char, count])
    return res

