def solve(tokens):
    """Evaluate an RPN expression.
    Tokens are strings representing integers (possibly negative) or the operators '+', '-', '*', '/'.
    Division should truncate toward zero.
    """
    if not tokens:
        return 0
    stack = []
    for t in tokens:
        if t in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                stack.append(a + b)
            elif t == '-':
                stack.append(a - b)
            elif t == '*':
                stack.append(a * b)
            else:  # division, truncate toward zero without using float
                # Python // floors toward -inf, so adjust for truncation toward zero
                if b == 0:
                    raise ZeroDivisionError('division by zero')
                # Compute absolute division and apply sign
                abs_result = abs(a) // abs(b)
                result = abs_result if (a >= 0) == (b >= 0) else -abs_result
                stack.append(result)
        else:
            # Operand
            stack.append(int(t))
    return stack[-1] if stack else 0

