def solve(grid):
    """Count islands in a possibly ragged 2D grid.
    grid: list of lists where each inner list may have different length.
    Cells with value 1 (int) are land; 0 is water. Connectivity 4-directional.
    Returns integer count. Handles empty grid and non-list inputs gracefully.
    """
    if not isinstance(grid, list) or not grid:
        return 0
    rows = len(grid)
    visited = [set() for _ in range(rows)]  # set of column indices visited per row
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if i < 0 or i >= rows:
                continue
            row = grid[i]
            if not isinstance(row, list):
                continue
            if j < 0 or j >= len(row):
                continue
            if (j in visited[i]) or row[j] != 1:
                continue
            visited[i].add(j)
            stack.append((i-1, j))
            stack.append((i+1, j))
            stack.append((i, j-1))
            stack.append((i, j+1))
    count = 0
    for i, row in enumerate(grid):
        if not isinstance(row, list):
            continue
        for j, val in enumerate(row):
            if val == 1 and (j not in visited[i]):
                dfs(i, j)
                count += 1
    return count

